import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
export const fixture={customerId:'33fd349e-a3c9-4647-8ce3-b32eec9099a0',companyId:'b36f6a30-18cd-4a70-8652-5b2da9b4eb64',A:'6d733fe9-766a-4e73-9e44-96562a164273',B:'1721d723-ca20-44e1-b9ce-1afc71a1ac2e'};
const sha=b=>createHash('sha256').update(b).digest('hex');
export async function runDraftCases({page,baseUrl,names,readback,record}){
 const path=`/admin/customers/${fixture.customerId}`;const out={kind:'NORMAL_MANUAL_SITE_DRAFT_CONTRACTS',scenarioIds:['SITE01.02','UI01.01'],posts:[],contracts:[],scope:'UNSIGNED_MANUAL_DRAFT_ONLY_NO_SEND_NO_MARKET_AUTHORITY'};
 const cases=[{site:fixture.A,name:names.A,contract_type:'fixed',starts_at:'2027-01-01',ends_at:'2027-12-31',binding_months:'12',fixed_price_ore_per_kwh:'95',monthly_fee_sek:'39'},{site:fixture.B,name:names.B,contract_type:'variable_hourly',starts_at:'2027-02-01',ends_at:'2029-01-31',binding_months:'24',spot_markup_ore_per_kwh:'6',monthly_fee_sek:'49'}];
 async function snapshot(tag){const x=await readback({tag,fixture,names});await record(tag,x);return x}
 async function post(form,intent){let response;try{[response]=await Promise.all([page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname===path,{timeout:90000}),form.locator('button[type=submit],button:not([type])').last().click()]);const body=await response.body();out.posts.push({intent,status:response.status(),bodySHA256:sha(body),bodyBytes:body.length});await record('post-'+intent,out.posts.at(-1));}catch(error){await snapshot('uncertain-'+intent);throw error}return response.status()}
 await snapshot('before-first-contract');
 for(const c of cases){await page.goto(baseUrl+path+'?tab=contracts',{waitUntil:'domcontentloaded'});const create=page.locator('details').filter({has:page.locator('summary').filter({hasText:/^Skapa avtal$/})}).last();if(!await create.evaluate(x=>x.open))await create.locator(':scope > summary').click();await page.getByLabel('Avtalskälla',{exact:true}).selectOption('manual');const form=page.locator('form').filter({has:page.getByRole('button',{name:'Skapa manuellt kundavtal',exact:true})});assert.equal(await form.count(),1);await form.locator('[name=contract_name]').fill(c.name);await form.locator('[name=signing_method][value=draft]').check();await form.locator('[name=site_id]').selectOption(c.site);await form.locator('[name=contract_type]').selectOption(c.contract_type);for(const [key,value]of Object.entries(c))if(!['site','name','contract_type'].includes(key))await form.locator(`[name=${key}]`).fill(value);await form.locator('[name=override_reason]').fill('Eget syntetiskt osignerat scenario-underlag; ingen signering eller utskick.');const code=await post(form,'CREATE_'+(c.site===fixture.A?'A':'B'));const result=await snapshot('after-create-'+c.site);assert.ok([200,303].includes(code),'Stop after actual status/readback, never retry CREATE');const row=result.matchingContracts.find(r=>r.contract_name===c.name);assert.ok(row,'Read actual committed contract before next mutation');assert.equal(row.company_id,fixture.companyId);assert.equal(row.customer_id,fixture.customerId);assert.equal(row.site_id,c.site);assert.equal(row.status,'draft');assert.equal(row.signed_at,null);out.contracts.push(row);}
 await page.goto(baseUrl+path+'?tab=contracts',{waitUntil:'domcontentloaded'});for(const c of cases)assert.ok(await page.getByText(c.name,{exact:true}).count()>0);await record('ui-customer-contract-list',{names:cases.map(c=>c.name),url:page.url()});
 const A=out.contracts[0];const form=page.locator('form').filter({has:page.locator(`[name=customer_contract_id][value="${A.id}"]`)});assert.equal(await form.count(),1);const parents=form.locator('xpath=ancestor::details');for(let i=await parents.count()-1;i>=0;i--){const d=parents.nth(i);if(!await d.evaluate(x=>x.open))await d.locator(':scope > summary').click();}assert.equal(await form.locator('[name=site_id]').inputValue(),fixture.A);assert.equal(await form.locator('[name=status]').inputValue(),'draft');await form.locator('[name=monthly_fee_sek]').fill('40');const code=await post(form,'EDIT_A_MONTHLY_ONLY');const after=await snapshot('after-edit-A');assert.ok([200,303].includes(code));assert.equal(after.matchingContracts.find(r=>r.id===A.id).monthly_fee_sek,40);out.state='LOCAL_DRAFT_BINDING_AND_UI_ID_PREDICATES_OBSERVED';await record('draft-ui-terminal',out);return out;
}

